Function average()

average &lt;- function(x, na.rm = FALSE) {
  # decide whether to remove missing values
  if (na.rm) {
    x &lt;- x[!is.na(x)]
  }
  # compute average
  avg &lt;- sum(x) / length(x)
  return(avg)
}

